/* A title has one card and multiple source records. No fuzzy title matching. */
(function(){
  'use strict';
  var aliases=Object.create(null),buckets=Object.create(null),sequence=0;
  function fields(item){var x=item&&item.xfields||{};if(typeof x==='string')try{x=JSON.parse(x);}catch(ignore){x={};}var normalized=Object.assign({},x);Object.keys(x).forEach(function(k){if(k.indexOf('xfvalue_')===0&&!normalized[k.slice(8)])normalized[k.slice(8)]=x[k];});return normalized;}
  function clean(value){return String(value||'').replace(/<[^>]*>/g,' ').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&(?:laquo|raquo|nbsp);/g,' ').replace(/\s+/g,' ').trim();}
  function normal(value){return clean(value).toLowerCase().replace(/ё/g,'е').replace(/\s+смотреть\s+онлайн.*$/,'').replace(/\s*\((?:(?:фильм|сериал)\s*)?(?:19|20)\d{2}(?:\s*[-–]\s*(?:19|20)\d{2})?\)\s*$/,'').replace(/\s*\(\d+(?:\s*[-–]\s*\d+)?\s*сезон[^)]*\)\s*$/,'').replace(/[^a-zа-я0-9]+/g,' ').trim();}
  function year(item){var m=clean(fields(item).year).match(/(?:19|20)\d{2}/);return m?m[0]:'';}
  function declared(value){value=clean(value).toLowerCase().replace(/[_-]+/g,' ');if(/^(?:series|serial|tv|tvseries|tv series|tv show|miniseries|сериал|телесериал|мультсериал|аниме сериал)$/.test(value))return'series';if(/^(?:movie|film|feature film|tv movie|short|фильм|мультфильм|аниме фильм)$/.test(value))return'movie';return'';}
  function kind(item){
    if(!item)return'';var verified=declared(item._kindVerified);if(verified)return verified;
    var x=fields(item),types=[item._kind,x.type,x.media_type,x.content_type,item.media_type].map(declared),raw=String(item._url||'')+' '+String(x.film||'')+' '+String(x.kinopoisk_url||'');
    var seasons=['number_of_seasons','numberOfSeasons','season_count','seasons_count'].some(function(key){var value=clean(x[key]===undefined?item[key]:x[key]),match=value.match(/^(\d{1,3})(?:\s*(?:сезон(?:а|ов)?|seasons?))?$/i);return match&&Number(match[1])>0&&Number(match[1])<=500;});
    if(types.indexOf('series')>=0||/\/(?:series|serials|serialy|zarubezhnye-serialy|multserialy)\//i.test(raw))return'series';
    if(types.indexOf('movie')>=0)return'movie';if(seasons||/мультсериал|телесериал|аниме[ -]сериал/i.test(x.janre||''))return'series';var hint=declared(item._kindHint);if(hint)return hint;
    return /\/(?:movie|films|filmy|multfilmy)\//i.test(raw)?'movie':'';
  }
  function names(item){var x=fields(item);return [normal(item.title),normal(x.original_title)].filter(function(v,i,a){return v&&a.indexOf(v)===i;});}
  function ids(item){var x=fields(item),out={},v=item._video;['kp','imdb','tmdb'].forEach(function(type){var raw=type==='kp'?(x.kinopoisk_id||x.kp_id||x.kinopoisk_url||''):type==='imdb'?(x.imdb_id||x.imdb_url||''):(x.tmdb_id||'');if(type==='kp'&&v&&v.aggregator==='kp')raw=v.titleId;var m=String(raw).match(type==='imdb'?/\btt\d+\b/:/^\d+$|\/(?:film|series)\/(\d+)/);if(m)out[type]=m[1]||m[0];});return out;}
  function same(a,b){
    if(!a||!b)return false;if(String(a.id)===String(b.id))return true;
    var ak=kind(a),bk=kind(b);if(ak&&bk&&ak!==bk)return false;
    var ai=ids(a),bi=ids(b),shared=false,conflict=false;Object.keys(ai).forEach(function(k){if(bi[k]){if(ai[k]===bi[k])shared=true;else conflict=true;}});if(conflict)return false;if(shared)return true;
    var ay=year(a),by=year(b);if(!ay||ay!==by||!ak||!bk)return false;
    var an=names(a),bn=names(b);return an.some(function(n){return bn.indexOf(n)>=0;});
  }
  function tokens(item){var out=[],external=ids(item),y=year(item);Object.keys(external).forEach(function(k){out.push(k+':'+external[k]);});if(y)names(item).forEach(function(n){out.push('name:'+y+':'+n);});return out;}
  function root(group){while(group&&group.parent)group=group.parent;return group;}
  function raw(item){var copy=Object.assign({},item);delete copy._alternatives;delete copy._group;delete copy._displayId;copy.xfields=Object.assign({},fields(item));return copy;}
  function idConflict(a,b){a=ids(a);b=ids(b);return Object.keys(a).some(function(k){return b[k]&&a[k]!==b[k];});}
  function compatible(group,item){return !group.variants.some(function(v){return idConflict(v,item)||kind(v)&&kind(item)&&kind(v)!==kind(item);});}
  function groupMatches(group,item){return group.variants.some(function(v){return same(v,item);})&&compatible(group,item);}
  function attach(group,item){
    var id=String(item.id),at=group.variants.findIndex(function(v){return String(v.id)===id;});
    if(at>=0){var previous=group.variants[at],next=raw(Object.assign({},previous,item));next.xfields=Object.assign({},fields(previous));Object.keys(fields(item)).forEach(function(k){if(fields(item)[k]!==''&&fields(item)[k]!==null&&fields(item)[k]!==undefined)next.xfields[k]=fields(item)[k];});group.variants[at]=next;}
    else group.variants.push(raw(item));
    aliases[id]=group;tokens(group.variants[at>=0?at:group.variants.length-1]).forEach(function(k){var bucket=buckets[k]||(buckets[k]=[]);if(bucket.indexOf(group)<0)bucket.push(group);});
  }
  function addOne(item){
    if(!item||!item.id||!item.title)return null;
    var candidates=[],id=String(item.id),existing=root(aliases[id]);
    if(existing){
      attach(existing,item);item=existing.variants.filter(function(v){return String(v.id)===id;})[0];
      // A verified type correction must not turn an unrelated same-name movie into a series.
      if(!compatible(existing,item)){existing.variants=existing.variants.filter(function(v){return String(v.id)!==id;});if(String(existing.id)===id)existing.id=existing.variants[0].id;delete aliases[id];existing=null;}
    }
    if(existing)candidates.push(existing);
    tokens(item).forEach(function(k){(buckets[k]||[]).forEach(function(g){g=root(g);if(candidates.indexOf(g)<0&&groupMatches(g,item))candidates.push(g);});});
    candidates.sort(function(a,b){return a.order-b.order;});var group=candidates[0]||{id:item.id,order:sequence++,variants:[]};
    candidates.slice(1).forEach(function(other){if(other.variants.every(function(v){return compatible(group,v);})){other.variants.forEach(function(v){attach(group,v);});other.parent=group;}});attach(group,item);return group;
  }
  function view(group){
    group=root(group);if(!group)return null;var variants=group.variants.slice(),best=variants[0];
    variants.forEach(function(v){if((v._detail?2:0)+(fields(v).film?4:0)>(best._detail?2:0)+(fields(best).film?4:0))best=v;});
    var item=raw(best),x=item.xfields;variants.forEach(function(v){Object.keys(fields(v)).forEach(function(k){if(k!=='film'&&!x[k])x[k]=fields(v)[k];});});
    ['full_story','short_story','descr'].forEach(function(key){if(!item[key])variants.some(function(v){if(v[key]){item[key]=v[key];return true;}return false;});});variants.some(function(v){if(declared(v._kindVerified)){item._kindVerified=v._kindVerified;return true;}return false;});item.id=group.id;item._group=true;item._displayId=best.id;item._alternatives=variants.map(raw);return item;
  }
  function find(id){return view(aliases[String(id)]);}
  function combine(items){var groups=[];(items||[]).forEach(function(item){var records=item&&item._alternatives&&item._alternatives.length?item._alternatives:[item];records.forEach(function(record){var g=addOne(record);if(g)groups.push(g);});});var seen=[];return groups.map(root).filter(function(g){if(seen.indexOf(g)>=0)return false;seen.push(g);return true;}).map(view);}
  function unresolved(items){var out=[],seen={};function collect(v){if(!v._kindVerified&&!seen[String(v.id)]){seen[String(v.id)]=true;out.push(raw(v));}}
    (items||[]).forEach(function(item){var group=root(aliases[String(item.id)]),records=group?group.variants:[item];records.forEach(function(v){var y=year(v),n=names(v);if(!y)return;tokens(v).filter(function(k){return k.indexOf('name:')===0;}).forEach(function(k){(buckets[k]||[]).forEach(function(g){g=root(g);g.variants.forEach(function(other){if(String(other.id)===String(v.id)||idConflict(other,v)||year(other)!==y||!names(other).some(function(name){return n.indexOf(name)>=0;}))return;if(!kind(v)||!kind(other)||kind(v)!==kind(other)){collect(v);collect(other);}});});});});});return out;}
  window.WePlayCatalogUnion={combine:combine,unresolved:unresolved,find:find,same:same,normal:normal,kind:kind,fields:fields,identifiers:ids,variants:function(item){var found=item&&find(item.id);return found?found._alternatives:item&&item._alternatives?item._alternatives:item?[raw(item)]:[];},canonical:function(id){var g=root(aliases[String(id)]);return g?String(g.id):String(id);}};
}());

progress.js.content:
/* Local viewing history. Stream addresses and provider credentials are never stored here. */
(function(){
  'use strict';
  var KEY='lord.watch-progress.v1',LIMIT=100,records=[];
  function finite(value,max){return typeof value==='number'&&isFinite(value)&&value>=0&&value<=max;}
  function number(value,max){var n=Number(value);return n>0&&n===Math.floor(n)&&n<=max?n:null;}
  function copy(value){return JSON.parse(JSON.stringify(value));}
  function metadata(item){
    var base=(item._alternatives||[]).filter(function(v){return String(v.id)===String(item.id);})[0]||item;
    var x=WePlayCatalogUnion.fields(item),out={id:String(item.id),title:String(item.title||'').slice(0,300),_source:base._source||'primary',_kind:WePlayCatalogUnion.kind(item),xfields:{}};
    ['year','original_title','janre','kinopoisk_id','kp_id','kinopoisk_url','imdb_id','imdb_url','tmdb_id','image','download_poster','poster','poster_url','thumbnail','thumb'].forEach(function(key){if(typeof x[key]==='string'||typeof x[key]==='number')out.xfields[key]=String(x[key]).slice(0,2000);});
    return out;
  }
  function valid(record){return record&&record.item&&typeof record.item.id==='string'&&record.item.id&&typeof record.item.title==='string'&&finite(record.position,86400000)&&finite(record.duration,86400000)&&finite(record.updatedAt,1e15)&&(!record.pending||number(record.season,500)&&number(record.episode,10000));}
  try{var stored=JSON.parse(localStorage.getItem(KEY)||'null');if(stored&&stored.version===1&&Array.isArray(stored.records))records=stored.records.filter(valid).slice(0,LIMIT).map(function(r){return Object.assign({},r,{item:metadata(r.item),aliases:(r.aliases||[]).filter(function(id){return typeof id==='string'&&id.length<200;}).slice(0,20)});});}catch(ignore){}
  function matches(record,item){
    if(!item||!item.id)return false;
    if(WePlayCatalogUnion.same(record.item,item))return true;
    var aliases=[String(item.id)].concat((item._alternatives||[]).map(function(v){return String(v.id);}));return aliases.some(function(id){return (record.aliases||[]).indexOf(id)>=0;});
  }
  function get(item){var found=records.filter(function(r){return matches(r,item);}).sort(function(a,b){return b.updatedAt-a.updatedAt;})[0];return found?copy(found):null;}
  function resumable(record){return !!record&&!record.completed&&(record.pending||record.position>=1000);}
  function persist(){
    records.sort(function(a,b){return b.updatedAt-a.updatedAt;});records=records.slice(0,LIMIT);
    try{localStorage.setItem(KEY,JSON.stringify({version:1,records:records}));}catch(ignore){
      // Retain the current session even when the TV's shared storage is full.
      try{localStorage.setItem(KEY,JSON.stringify({version:1,records:records.slice(0,20)}));}catch(full){}
    }
  }
  function update(item,sample){
    if(!item||!item.id||!sample||!finite(sample.position,86400000)||!finite(sample.duration,86400000)||sample.position<1000&&!sample.ended)return null;
    var duration=sample.duration,position=duration?Math.min(sample.position,duration):sample.position,ended=!!sample.ended||duration>0&&position/duration>=.95&&duration-position<=120000;
    var next=ended&&sample.next&&number(sample.next.season,500)&&number(sample.next.episode,10000),previous=get(item);
    var record={item:metadata(item),aliases:[String(item.id)].concat((item._alternatives||[]).map(function(v){return String(v.id);})),position:next?0:Math.round(position),duration:next?0:Math.round(duration),season:next?Number(sample.next.season):number(sample.season,500),episode:next?Number(sample.next.episode):number(sample.episode,10000),pending:!!next,completed:ended&&!next,sourceId:String(sample.sourceId||''),updatedAt:Math.max(Date.now(),records.length?records[0].updatedAt+1:0)};
    if(previous)record.aliases=record.aliases.concat(previous.aliases||[]);record.aliases=record.aliases.filter(function(id,i,a){return a.indexOf(id)===i;}).slice(0,20);
    records=records.filter(function(r){return !matches(r,item);});records.unshift(record);persist();return copy(record);
  }
  function reset(item){records=records.filter(function(r){return !matches(r,item);});persist();}
  function list(){var out=[];records.forEach(function(r){if(resumable(r)&&!out.some(function(other){return matches(other,r.item);}))out.push(copy(r));});return out.slice(0,20);}
  function time(ms){var seconds=Math.floor(ms/1000),h=Math.floor(seconds/3600),m=Math.floor(seconds/60)%60,s=seconds%60;return(h?h+':':'')+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');}
  function label(record){if(!record)return'';var parts=[];if(record.season&&record.episode)parts.push('Сезон '+record.season,'Серия '+record.episode);if(record.pending)parts.push('Следующая серия');else if(record.position)parts.push(time(record.position)+(record.duration?' из '+time(record.duration):''));return parts.join(' · ');}
  window.WePlayProgress={get:get,update:update,reset:reset,list:list,canResume:resumable,label:label,ratio:function(r){return r&&r.duration>0?Math.max(0,Math.min(1,r.position/r.duration)):0;}};
}());

series.js.content:
/* Whole-series metadata. A final available episode does not prove a show ended. */
(function(){
  'use strict';
  function clean(value){return String(value===undefined||value===null?'':value).replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();}
  function count(value){if(typeof value!=='number'&&typeof value!=='string')return null;var m=clean(value).match(/^(\d+)(?:\s*(?:сезон(?:а|ов)?|seasons?))?$/i),n=m&&Number(m[1]);return n>0&&n<=500?n:null;}
  function status(value){
    var text=clean(value).toLowerCase().replace(/ё/g,'е').replace(/\s*\((?:19|20)\d{2}\)\s*$/,'').replace(/[.!]$/,'');
    if(/^(?:ended|completed|finished|завершен|завершился|завершено|закончен)$/.test(text))return'ended';
    if(/^(?:canceled|cancelled|закрыт|отменен)$/.test(text))return'canceled';
    if(/^(?:returning|returning series|ongoing|продолжается|возвращается|сериал продолжается)$/.test(text))return'returning';
    if(/^(?:production|in production|в производстве)$/.test(text))return'production';
    if(/^(?:planned|анонсирован|запланирован)$/.test(text))return'planned';
    if(/^(?:pilot|пилот)$/.test(text))return'pilot';return null;
  }
  function normalize(data){if(!data)return null;var seasons=count(data.seasons),state=status(data.status);return seasons||state?{seasons:seasons,status:state}:null;}
  function fromItem(item){
    if(WePlayCatalogUnion.kind(item)!=='series')return null;var x=WePlayCatalogUnion.fields(item),seasons=null,state=null;
    ['number_of_seasons','numberOfSeasons','season_count','seasons_count'].some(function(key){seasons=count(x[key]===undefined?item[key]:x[key]);return !!seasons;});
    ['series_status','show_status','status','creativeWorkStatus'].some(function(key){state=status(x[key]===undefined?item[key]:x[key]);return !!state;});return normalize({seasons:seasons,status:state});
  }
  function merge(base,preferred){base=normalize(base);preferred=normalize(preferred);return normalize({seasons:preferred&&preferred.seasons||base&&base.seasons,status:preferred&&preferred.status||base&&base.status});}
  function formatCount(value){var n=count(value);if(!n)return'';var ten=n%10,hundred=n%100;return n+' '+(ten===1&&hundred!==11?'сезон':ten>=2&&ten<=4&&(hundred<12||hundred>14)?'сезона':'сезонов');}
  function label(value){return{ended:'Завершён',canceled:'Закрыт',returning:'Продолжается',production:'В производстве',planned:'Анонсирован',pilot:'Пилот'}[status(value)]||'';}
  function documentOf(value){return value&&value.querySelectorAll?value:new DOMParser().parseFromString(String(value||''),'text/html');}
  function seriesId(page){try{var url=new URL(page),match=url.hostname==='www.themoviedb.org'&&url.pathname.match(/^\/tv\/(\d+)(?:-|\/|$)/);return match&&match[1]||null;}catch(ignore){return null;}}
  function parsePage(page,url){
    var id=seriesId(url);if(!id)return null;var doc=documentOf(page),info={seasons:null,status:null,seasonsURL:null,at:Date.now()};
    function schema(value){if(!value||typeof value!=='object')return;if(Array.isArray(value)){value.forEach(schema);return;}if(value['@type']==='TVSeries'){info.seasons=count(value.numberOfSeasons)||info.seasons;info.status=status(value.creativeWorkStatus)||info.status;}if(value['@graph'])schema(value['@graph']);}
    Array.prototype.forEach.call(doc.querySelectorAll('script[type="application/ld+json"]'),function(script){try{schema(JSON.parse(script.textContent));}catch(ignore){}});
    Array.prototype.forEach.call(doc.querySelectorAll('section.facts p'),function(row){var strong=row.querySelector('strong');if(!strong)return;var key=clean(strong.textContent),value=clean(row.textContent).slice(key.length).replace(/^\s*:\s*/,'').trim();if(/^(?:статус|status):?$/i.test(key))info.status=status(value)||info.status;if(/^(?:сезонов|количество сезонов|number of seasons):?$/i.test(key))info.seasons=count(value)||info.seasons;});
    Array.prototype.some.call(doc.querySelectorAll('a[href]'),function(link){try{var target=new URL(link.getAttribute('href'),url);if(target.hostname==='www.themoviedb.org'&&new RegExp('^/tv/'+id+'(?:-[^/]+)?/seasons/?$').test(target.pathname)){target.searchParams.set('language','ru-RU');info.seasonsURL=target.href;return true;}}catch(ignore){}return false;});
    return info.seasons||info.status||info.seasonsURL?info:null;
  }
  function parseSeasons(page,url){
    var id=seriesId(url);if(!id||!/\/seasons\/?$/.test(new URL(url).pathname))return null;var doc=documentOf(page),seen={};
    Array.prototype.forEach.call(doc.querySelectorAll('.season_wrapper .season h2 a[href],.season_wrapper .season h3 a[href]'),function(link){try{var target=new URL(link.getAttribute('href'),url),match=target.hostname==='www.themoviedb.org'&&target.pathname.match(new RegExp('^/tv/'+id+'(?:-[^/]+)?/season/(\\d+)/?$'));if(match&&Number(match[1])>0)seen[Number(match[1])]=true;}catch(ignore){}});
    return count(Object.keys(seen).length);
  }
  window.WePlaySeries={count:count,status:status,normalize:normalize,fromItem:fromItem,merge:merge,formatCount:formatCount,label:label,parsePage:parsePage,parseSeasons:parseSeasons};
}());

seasons.js.content:
/* Available seasons come from player data, independently of the metadata total. */
(function(){
  'use strict';
  function number(value){if(typeof value!=='number'&&typeof value!=='string'||String(value).trim()==='')return null;var n=Number(value);return isFinite(n)&&n===Math.floor(n)&&n>0&&n<=500?n:null;}
  function episodeNumber(value){var n=Number(value);return value!==null&&value!==undefined&&String(value).trim()!==''&&isFinite(n)&&n===Math.floor(n)&&n>0&&n<=10000?n:null;}
  function ordered(episodes){return (episodes||[]).map(function(e,i){return {episode:e,index:i};}).sort(function(a,b){return (number(a.episode.season)||10001)-(number(b.episode.season)||10001)||(episodeNumber(a.episode.episode)||10001)-(episodeNumber(b.episode.episode)||10001)||a.index-b.index;}).map(function(entry){return entry.episode;});}
  function startIndex(episodes,season){season=number(season);if(!season)return -1;var found=-1,first=Infinity;(episodes||[]).forEach(function(e,i){if(number(e.season)!==season)return;var order=episodeNumber(e.episode)||10001;if(found<0||order<first){found=i;first=order;}});return found;}
  function resumeIndex(episodes,resume){if(!resume)return -1;var season=number(resume.season),episode=episodeNumber(resume.episode);if(!season||!episode)return episodes.length===1&&!number(episodes[0].season)?0:-1;return episodes.findIndex(function(e){return number(e.season)===season&&episodeNumber(e.episode)===episode;});}
  function group(episodes){
    var groups={};ordered(episodes).forEach(function(e,index){var season=number(e.season);if(!season)return;var episode=episodeNumber(e.episode),entry=groups[season]||(groups[season]={number:season,count:0,firstEpisode:episode,seen:{}}),key=episode===null?'index:'+index:String(episode);if(!entry.seen[key]){entry.seen[key]=true;entry.count++;}});
    return Object.keys(groups).map(function(key){var entry=groups[key];return {number:entry.number,count:entry.count,firstEpisode:entry.firstEpisode};}).sort(function(a,b){return a.number-b.number;});
  }
  function combine(lists){var found={};(lists||[]).forEach(function(list){(list||[]).forEach(function(s){if(number(s.number)&&!found[s.number])found[s.number]=s;});});return Object.keys(found).map(function(key){return found[key];}).sort(function(a,b){return a.number-b.number;});}
  function countLabel(n){var ten=n%10,hundred=n%100;return n+' '+(ten===1&&hundred!==11?'серия':ten>=2&&ten<=4&&(hundred<12||hundred>14)?'серии':'серий');}
  window.WePlaySeasons={number:number,ordered:ordered,startIndex:startIndex,resumeIndex:resumeIndex,group:group,combine:combine,countLabel:countLabel};
}());

duration.js.content:
/* Catalog runtimes are minutes; player and playlist durations are seconds. */
(function(){
  'use strict';
  var cache={},pending={},failed={},KEY='lord.duration.v1';
  try{cache=JSON.parse(localStorage.getItem(KEY)||'{}')||{};}catch(ignore){}
  function value(low,high,episode,approximate){low=Number(low);high=Number(high);if(!isFinite(low)||!isFinite(high)||low<=0||high<low||high>1440)return null;low=Math.max(1,Math.round(low));high=Math.max(low,Math.round(high));return{min:low,max:high,episode:!!episode,approximate:!!approximate};}
  function minutes(raw){
    if(raw===null||raw===undefined||typeof raw==='object')return null;
    var text=String(raw).replace(/<[^>]*>/g,' ').replace(/&nbsp;/g,' ').replace(/\s+/g,' ').trim().toLowerCase(),m;
    if(!text||/^[-−–—]/.test(text))return null;
    if(/^\d+(?:[.,]\d+)?$/.test(text)){var n=Number(text.replace(',','.'));return n>0&&n<=1440?{min:n,max:n}:null;}
