    var hours=/(\d+(?:[.,]\d+)?)\s*(?:час(?:а|ов)?|ч\.?|hours?|h)(?=\s|\d|[./]|$)/.exec(text),mins=/(\d+(?:[.,]\d+)?)\s*(?:мин(?:ут[аы]?)?\.?|minutes?|min|m)(?=\s|[./]|$)/.exec(text),secs=/(\d+(?:[.,]\d+)?)\s*(?:сек(?:унд[аы]?)?|seconds?|sec|s)(?=\s|[./]|$)/.exec(text);
