/* An optional, remote-friendly update action beside Support on every page. */
(function(){
  'use strict';
  var opened=false,trigger=null,callback=null,saved=[],scroll=0,modal=document.createElement('div');modal.id='update-modal';modal.hidden=true;
  modal.innerHTML='<section class="player-confirm" role="dialog" aria-modal="true" aria-labelledby="update-title" aria-describedby="update-description"><h2 id="update-title">Обновить WePlay?</h2><p id="update-description"></p><div class="confirm-actions"><button id="update-apply" class="primary focusable">Обновить сейчас</button><button id="update-later" class="secondary focusable">Позже</button></div></section>';
  document.getElementById('stage').appendChild(modal);var apply=modal.querySelector('#update-apply'),later=modal.querySelector('#update-later'),description=modal.querySelector('#update-description');
  function pending(){return window.WePlayRuntime&&WePlayRuntime.snapshot().pendingVersion;}
  function preferred(){return document.activeElement===later?later:apply;}
  function close(restore){if(!opened)return;opened=false;modal.hidden=true;document.getElementById('stage').classList.remove('update-open');saved.forEach(function(entry){if(entry.value===null)entry.node.removeAttribute('aria-hidden');else entry.node.setAttribute('aria-hidden',entry.value);});saved=[];var previous=trigger,done=callback;trigger=null;callback=null;if(previous)previous.setAttribute('aria-expanded','false');if(restore!==false){if(done)done();WePlayFocus.focus(previous,false);document.getElementById('content').scrollTop=scroll;}}
  function open(button,onClose){if(opened||!pending()||window.WePlaySupport&&WePlaySupport.isOpen()||!document.getElementById('player').hidden)return;trigger=button;callback=onClose;scroll=document.getElementById('content').scrollTop;saved=['content','sidebar'].map(function(id){var node=document.getElementById(id);return{node:node,value:node.getAttribute('aria-hidden')};});saved.forEach(function(entry){entry.node.setAttribute('aria-hidden','true');});description.textContent='Версия '+pending()+' уже загружена. После обновления WePlay перезапустится. История просмотра и избранное сохранятся.';apply.disabled=later.disabled=false;opened=true;modal.hidden=false;document.getElementById('stage').classList.add('update-open');button.setAttribute('aria-expanded','true');WePlayFocus.focus(apply,false);}
  function sync(){var version=pending();document.querySelectorAll('.update-action').forEach(function(button){button.hidden=!version;if(button.parentNode&&button.parentNode.classList.contains('update-control'))button.parentNode.hidden=!version;button.setAttribute('aria-label',version?'Доступно обновление WePlay '+version:'Обновление WePlay');});if(opened&&version)description.textContent='Версия '+version+' уже загружена. После обновления WePlay перезапустится. История просмотра и избранное сохранятся.';}
  /* Older installed shells poll hourly. Keep their signed UI up to date while browsing. */
  function checkAvailable(){
    var runtime=window.WePlayRuntime;if(!runtime||document.hidden||window.WePlayNativePlayer&&WePlayNativePlayer.active||document.body.classList.contains('playback-open'))return;
    var state=runtime.snapshot();if(!state.confirmed||state.pendingVersion||state.checking||Date.now()-state.lastCheck<15000)return;
    Promise.resolve(runtime.check()).then(sync,function(){});
  }
  setTimeout(checkAvailable,6000);setInterval(checkAvailable,60000);
  document.addEventListener('visibilitychange',function(){if(!document.hidden)checkAvailable();});
  window.addEventListener('online',checkAvailable);
  function control(onOpen,onClose){var wrapper=document.createElement('span'),aura=document.createElement('span');wrapper.className='update-control';wrapper.hidden=!pending();aura.className='update-aura';aura.setAttribute('aria-hidden','true');wrapper.appendChild(aura);var b=document.createElement('button');b.type='button';b.className='secondary focusable update-action';b.id='update-open';b.setAttribute('aria-haspopup','dialog');b.setAttribute('aria-controls','update-modal');b.setAttribute('aria-expanded','false');b.innerHTML='<span class="icon" aria-hidden="true">'+WEPLAY_ICONS['download-simple']+'</span><span class="button-label">Доступна новая версия</span>';b.hidden=!pending();b.setAttribute('aria-label',pending()?'Доступно обновление WePlay '+pending():'Обновление WePlay');b.addEventListener('click',function(){if(onOpen)onOpen();open(b,onClose);});wrapper.appendChild(b);return wrapper;}
  apply.addEventListener('click',function(){if(!window.WePlayRuntime||typeof WePlayRuntime.applyUpdate!=='function')return;apply.disabled=true;Promise.resolve(WePlayRuntime.applyUpdate()).then(function(result){if(result&&result.state==='restarting')return;apply.disabled=false;description.textContent=result&&result.state==='deferred'?'Завершите просмотр, затем обновите WePlay.':'Не удалось запустить обновление. Попробуйте ещё раз.';}).catch(function(){apply.disabled=false;description.textContent='Не удалось запустить обновление. Попробуйте ещё раз.';});});
  later.addEventListener('click',function(){close(true);});window.addEventListener('weplay:update-ready',sync);
  document.addEventListener('focusin',function(event){if(opened&&!modal.contains(event.target)){event.stopImmediatePropagation();WePlayFocus.focus(preferred(),false);}},true);
  document.addEventListener('keydown',function(event){if(!opened)return;var k=event.keyCode||event.which;if(k!==10009&&k!==27&&k!==13&&k!==32&&k!==9&&!(k>=37&&k<=40))return;event.preventDefault();event.stopImmediatePropagation();if(event.repeat)return;if(k===10009||k===27)close(true);else if(k===13||k===32)preferred().click();else WePlayFocus.focus(preferred()===apply?later:apply,false);},true);
  document.addEventListener('tizenhwkey',function(event){if(opened&&event.keyName==='back'){event.preventDefault();event.stopImmediatePropagation();close(true);}},true);
  window.WePlayUpdatesUI={control:control,close:close,isOpen:function(){return opened;}};
}());

