style.css.content:
@font-face{font-family:Manrope;src:url('fonts/manrope-regular.ttf')}
@font-face{font-family:Manrope;src:url('fonts/manrope-bold.ttf');font-weight:700}
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#000;color:#f5f5f5;font-family:Manrope,sans-serif}
button,input,select{font:inherit;outline:none}
button{cursor:pointer;transition:background-color 150ms cubic-bezier(.2,0,0,1),color 150ms cubic-bezier(.2,0,0,1),transform 150ms cubic-bezier(.2,0,0,1)}
button:focus,input:focus,select:focus{outline:4px solid #fff;outline-offset:6px}
button:active{transform:scale(.96)}
button:disabled{opacity:.4;cursor:default}
[hidden]{display:none!important}
.icon{display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;flex-shrink:0}
.icon svg{display:block;width:100%;height:100%;fill:currentColor}
.button-label{display:block}
#stage{position:absolute;width:1920px;height:1080px;transform-origin:top left;background:#101010;overflow:hidden}
#sidebar{position:absolute;z-index:12;left:0;top:0;bottom:0;width:112px;padding:32px 24px;background:#181818;overflow:hidden}
#sidebar.expanded{left:32px;top:32px;bottom:32px;width:368px;padding:16px;background:rgba(24,24,24,.94);border:1px solid rgba(255,255,255,.12);border-radius:48px;box-shadow:0 24px 64px rgba(0,0,0,.36)}
.brand{height:64px;display:flex;align-items:center;white-space:nowrap;font-weight:700}
.brand-logo{display:block;object-fit:contain;flex-shrink:0}
.brand .brand-logo{width:48px;height:48px;margin:0 8px}
.brand-name{display:none;font-size:24px;line-height:32px;margin-left:8px;letter-spacing:-.5px}
#sidebar.expanded .brand-name{display:block}
#sidebar-clock{display:none;margin-left:auto;margin-right:16px;font-size:18px;line-height:28px;font-weight:400;color:#bcbcbc}
#sidebar.expanded #sidebar-clock{display:block}
#navigation{margin-top:24px}
nav button{display:flex;align-items:center;width:64px;height:64px;margin:0 0 8px;padding:12px;text-align:left;color:#bcbcbc;border:0;border-radius:32px;background:transparent;font-size:24px;line-height:32px;font-weight:400;white-space:nowrap}
#navigation .icon{width:40px;height:40px;padding:8px;border-radius:20px;background:rgba(255,255,255,.08)}
nav .button-label{display:none;margin-left:16px}
#sidebar.expanded nav button{width:100%}
#sidebar.expanded nav .button-label{display:block}
nav button.current{color:#fff;background:rgba(255,255,255,.08);font-weight:700}
nav button:hover{color:#fff;background:#272727}
nav button:focus{color:#111;background:#f5f5f5;outline:none;box-shadow:none;font-weight:700}
#navigation button:focus .icon{background:rgba(0,0,0,.12)}
#nav-7{margin-bottom:16px}
#content{position:absolute;left:112px;top:0;width:1808px;height:1080px;overflow-y:auto;padding:48px;scrollbar-width:none}
#content::-webkit-scrollbar,.native-menu::-webkit-scrollbar{display:none}
#content:focus{outline:none}
#sidebar-scrim{position:absolute;left:0;right:0;top:0;bottom:0;z-index:11;background:rgba(0,0,0,.24);opacity:0;visibility:hidden;pointer-events:none;transition:opacity 150ms cubic-bezier(.2,0,0,1)}
.sidebar-open #sidebar-scrim{opacity:1;visibility:visible;pointer-events:auto}
.playback-open #sidebar-scrim{display:none}
@supports ((backdrop-filter:blur(32px)) or (-webkit-backdrop-filter:blur(32px))){#sidebar.expanded{background:rgba(24,24,24,.68);backdrop-filter:blur(32px);-webkit-backdrop-filter:blur(32px)}}
.page-view{position:relative;min-height:100%;opacity:1;transform:translateY(0);transition:opacity 180ms cubic-bezier(.23,1,.32,1),transform 180ms cubic-bezier(.23,1,.32,1)}
.page-view.route-entering{opacity:0;transform:translateY(12px)}
.page-view.route-leaving{position:absolute;z-index:2;pointer-events:none;min-height:0;transition-duration:150ms}
.page-view.route-out{opacity:0;transform:translateY(-8px)}
.page-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}
.page-header h1{font-size:48px;line-height:56px;letter-spacing:-1.5px;margin:0;font-weight:700;max-width:1440px}
.page-header .count{font-size:20px;line-height:28px;color:#777;font-weight:700}
.header-tools{display:flex;align-items:center;margin-left:32px;flex-shrink:0}
.error button,.load-more button{margin-right:24px}
.count,.muted{color:#a0a0a0;font-size:20px;line-height:28px}
.eyebrow{font-size:14px;line-height:20px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#bcbcbc;margin:0 0 12px}
.featured{position:relative;height:432px;overflow:hidden;background:#1f1f1f;border-radius:16px}
.featured-slide{position:absolute;top:0;left:0;width:100%;height:100%;opacity:1;transform:translateX(0);transition:opacity 600ms cubic-bezier(.77,0,.175,1),transform 600ms cubic-bezier(.23,1,.32,1)}
.featured-slide.slide-leaving{pointer-events:none}
.featured-body{position:relative;z-index:2;width:55%;height:100%;padding:32px 40px;display:flex;flex-direction:column;justify-content:center}
.featured-title{font-size:48px;line-height:56px;letter-spacing:-1.5px;font-weight:700;margin:0;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}
.featured-meta{font-size:20px;line-height:28px;color:#bcbcbc;margin:12px 0 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.featured-description{color:#bcbcbc;font-size:20px;line-height:28px;margin:12px 0 24px;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:1;overflow:hidden}
.featured-slide.long-title .featured-description{display:none}
.featured-slide.long-title .actions{margin-top:24px}
.featured .actions{flex-wrap:nowrap;margin-bottom:0}
.featured .actions button{font-size:24px;line-height:32px;padding:12px 24px;margin-bottom:0;white-space:nowrap}
.featured-art{position:absolute;top:0;right:0;width:45%;height:100%;overflow:hidden;background:#272727}
.featured-art img{width:100%;height:100%;object-fit:cover;object-position:50% 24%;display:block}
.featured-art.unavailable img{display:none}
.featured-pager{position:absolute;right:24px;bottom:24px;display:flex;align-items:center;z-index:3}
.featured-position{font-size:18px;line-height:28px;font-weight:700;color:#fff;background:rgba(0,0,0,.64);border-radius:12px;padding:8px 12px;margin-right:8px;font-variant-numeric:tabular-nums}
.circle-button{width:48px;height:48px;padding:12px;border:0;border-radius:24px;background:rgba(0,0,0,.72);color:#fff;margin-left:8px}
.circle-button .icon{width:24px;height:24px}
.circle-button .button-label{display:none}
.circle-button:focus,.circle-button:hover{background:#fff;color:#111}
.section-heading{display:flex;align-items:center;justify-content:space-between;margin:32px 0 16px}
.section-heading h2{font-size:30px;line-height:36px;letter-spacing:-.5px;margin:0}
.text-button{background:transparent;color:#bcbcbc;border:0;border-radius:8px;padding:8px 12px;font-size:20px;line-height:28px}
.text-button:focus,.text-button:hover{background:#313131;color:#fff}
.grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));grid-gap:32px 24px}
.movie-card{position:relative;border:0;border-radius:12px;padding:0 0 8px;text-align:left;color:#f5f5f5;background:transparent;min-width:0}
.movie-card:focus{outline:none}
.poster-wrap{position:relative;width:100%;height:392px;background:#272727;border:1px solid rgba(255,255,255,.1);border-radius:12px;overflow:hidden;transition:transform 150ms cubic-bezier(.2,0,0,1),box-shadow 150ms cubic-bezier(.2,0,0,1)}
.view-home .poster-wrap{height:352px}
.movie-card:focus .poster-wrap{box-shadow:0 0 0 5px #fff;transform:scale(1.025)}
.movie-card:hover .poster-wrap{box-shadow:0 0 0 3px #bcbcbc}
.movie-card:focus:hover .poster-wrap{box-shadow:0 0 0 5px #fff}
.poster-wrap img{height:100%;width:100%;object-fit:cover;object-position:50% 20%;display:block}
.poster-fallback{height:100%;display:flex;align-items:center;justify-content:center;padding:24px;color:#777;font-size:24px;text-align:center}
.movie-title{font-size:20px;line-height:28px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding:16px 0 0}
.movie-meta{font-size:18px;line-height:28px;padding:4px 0;color:#929292;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.watch-progress{position:absolute;left:12px;right:12px;bottom:12px;height:4px;border-radius:2px;background:rgba(255,255,255,.3);box-shadow:0 1px 4px rgba(0,0,0,.5);overflow:hidden}
.watch-progress span,.detail-resume-track span{display:block;width:100%;height:100%;background:#f5f5f5;transform-origin:left center}
.detail-resume{max-width:560px;margin:24px 0 0}
.detail-resume-label{font-size:20px;line-height:28px;color:#ccc;margin:0 0 12px;font-variant-numeric:tabular-nums}
.detail-resume-track{height:4px;border-radius:2px;background:rgba(255,255,255,.24);overflow:hidden}
.rating{position:absolute;top:12px;left:12px;background:rgba(0,0,0,.8);color:#fff;border-radius:8px;padding:4px 8px;font-size:18px;line-height:24px;font-weight:700}
.filters{display:flex;flex-wrap:wrap;margin:32px 0 24px}
.filters label{display:block;margin:0 16px 16px 0;color:#a0a0a0;font-size:18px;line-height:28px}
.filters select{display:block;background:#272727;border:1px solid #444;border-radius:12px;color:#f5f5f5;font-size:20px;line-height:28px;padding:12px 16px;max-width:320px;margin-top:8px}
.primary,.secondary{display:inline-flex;align-items:center;justify-content:center;border-radius:12px;font-size:24px;line-height:32px;font-weight:700;padding:16px 24px;border:0}
.primary .icon,.secondary .icon{margin-right:12px}
.primary{color:#111;background:#f5f5f5}
.primary:hover{background:#dcdcdc}
.secondary{color:#f5f5f5;background:#313131}
.secondary:hover{background:#444}
.secondary:focus{background:#f5f5f5;color:#111}
.load-more{text-align:center;margin:40px 0 24px}
.empty,.error{padding:64px 48px;background:#1f1f1f;border-radius:16px;font-size:24px;line-height:36px;color:#bcbcbc}
.empty h2,.error h2{margin:0 0 16px;color:#f5f5f5;font-size:30px;line-height:36px}
.empty p,.error p{margin:0 0 24px}
.search-form{display:flex;margin:32px 0 40px}
.search-form input{flex:1;min-width:0;background:#272727;border:1px solid #444;border-radius:12px;padding:16px 24px;color:#fff;font-size:30px;line-height:36px;margin-right:24px}
.search-form input::placeholder{color:#929292}
.search-help{color:#a0a0a0;font-size:24px;line-height:36px}
.collection-grid{display:grid;grid-template-columns:repeat(4,1fr);grid-gap:24px;margin-top:32px}
.collection{background:#272727;color:#f5f5f5;border:1px solid #313131;border-radius:16px;padding:32px;text-align:left;font-size:24px;line-height:32px;min-height:144px}
.collection:focus{background:#f5f5f5;color:#111}
.detail-back{margin-bottom:40px;background:transparent;color:#bcbcbc;padding:12px 16px}
.detail{display:flex;align-items:flex-start}
.detail-poster{order:2;width:448px;height:672px;flex-shrink:0;margin-left:64px;border-radius:16px;object-fit:cover;background:#272727;border:1px solid rgba(255,255,255,.1)}
.detail-content{order:1;padding:16px 0 48px;min-width:0;flex:1}
.detail-content h1{font-size:72px;line-height:80px;letter-spacing:-2px;margin:0 0 16px;overflow-wrap:break-word}
.original-title{color:#929292;font-size:24px;line-height:32px;margin:0 0 24px}
.metadata{font-size:20px;line-height:32px;color:#bcbcbc;margin-bottom:32px;max-width:1040px}
.actions{display:flex;flex-wrap:wrap;margin:0 0 24px}
.actions button{margin:0 16px 16px 0}
.description{font-size:24px;line-height:36px;color:#bcbcbc;white-space:pre-line;overflow-wrap:break-word;max-width:1040px;margin:0 0 32px}
.facts{font-size:20px;line-height:32px;color:#929292;margin:16px 0 0;max-width:1040px}
.source-caption{color:#a0a0a0;font-size:18px;line-height:28px;margin:8px 0 24px}
#player{position:absolute;top:0;left:0;right:0;bottom:0;width:100%;height:100%;margin:0;padding:0;overflow:hidden;background:#000;z-index:20}
#player-surface{position:absolute;top:0;left:0;width:100%;height:100%;border:0;z-index:1}
#player-toolbar{position:absolute;top:0;left:0;right:0;display:flex;align-items:center;padding:32px 48px;background:#181818;z-index:4}
#player-toolbar button{border:0;background:#313131;color:#fff;border-radius:12px;padding:12px 24px;margin-right:16px;font-size:20px;line-height:28px}
#player-title{flex:1;font-size:24px;line-height:32px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;padding:0 24px}
#player-hint{position:absolute;z-index:4;bottom:32px;left:48px;right:48px;text-align:center;color:#bcbcbc;background:rgba(24,24,24,.92);padding:12px 24px;border-radius:12px;font-size:20px;line-height:28px}
#player-status{position:absolute;z-index:3;top:40%;left:20%;right:20%;text-align:center;background:#181818;border-radius:16px;padding:32px;font-size:24px;line-height:36px;color:#bcbcbc}
#player-status:empty{display:none}
#toast{position:absolute;bottom:48px;left:560px;right:288px;padding:16px 32px;background:#f5f5f5;color:#111;border-radius:16px;z-index:50;font-size:24px;line-height:32px;text-align:center;box-shadow:0 8px 32px rgba(0,0,0,.3)}
.avplay-active,.avplay-active #stage,.avplay-active #player,.avplay-active #player-surface{background:transparent!important}
.playback-open #sidebar,.playback-open #content,.playback-open .route-leaving,.native-playing #sidebar,.native-playing #content,.native-playing .route-leaving{opacity:0!important;visibility:hidden!important;pointer-events:none}
.playback-open #toast{display:none!important}
#native-video{position:absolute;left:0;top:0;width:100%;height:100%;object-fit:contain}
.native-controls{position:absolute;bottom:112px;left:48px;right:48px;z-index:5;padding:32px;background:rgba(24,24,24,.96);border-radius:24px;border:1px solid rgba(255,255,255,.12)}
.native-now{display:flex;align-items:center}
.native-now-copy{flex:1;min-width:0}
.native-now-title{font-size:30px;line-height:36px;letter-spacing:-.5px;margin:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.native-now-episode{font-size:20px;line-height:28px;color:#bcbcbc;margin:8px 0 0}
.native-state{font-size:18px;line-height:28px;color:#f5f5f5;background:#313131;border-radius:8px;padding:4px 12px;margin-left:32px}
.native-seek{display:flex;align-items:center;margin:24px 0}
.native-time{font-size:20px;line-height:28px;color:#f5f5f5;font-variant-numeric:tabular-nums;white-space:nowrap;min-width:64px}
.native-time:last-child{text-align:right}
.native-timeline{flex:1;height:4px;background:rgba(255,255,255,.28);border-radius:2px;overflow:hidden;margin:0 16px}
.native-timeline-fill{display:block;height:100%;width:100%;background:#fff;transform:scaleX(0);transform-origin:left center}
.native-actions{display:flex;align-items:stretch}
.native-actions .native-control{margin-right:12px;padding:16px 24px;font-size:24px;line-height:32px;min-height:88px;min-width:144px;flex-shrink:0}
.native-control .control-copy{display:block;text-align:left;min-width:0}
.control-label{display:block;white-space:nowrap}
.control-caption{display:block;font-size:18px;line-height:28px;font-weight:400;color:#bcbcbc;margin-top:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.native-control:focus .control-caption{color:#444}
#native-toggle{min-width:208px}
#native-audio{min-width:256px;max-width:312px}
#native-episodes{min-width:256px}
#native-exit{margin-right:0;margin-left:auto}
.native-control:disabled{opacity:.5}
.native-control,.native-menu-grid button{transition:transform 150ms cubic-bezier(.2,0,0,1)}
.native-menu{position:absolute;z-index:10;left:240px;right:240px;top:160px;max-height:720px;overflow-y:auto;padding:40px;background:#1f1f1f;border:1px solid #444;border-radius:24px;box-shadow:0 24px 80px rgba(0,0,0,.56);scrollbar-width:none}
.native-menu h2{font-size:36px;line-height:40px;letter-spacing:-.5px;margin:0 0 32px}
.native-menu-grid{display:grid;grid-template-columns:repeat(4,1fr);grid-gap:24px}
.native-menu-grid button{min-height:80px;text-align:center;overflow-wrap:break-word}
.native-menu-grid button.selected{background:#444;box-shadow:inset 0 0 0 1px #777}
.native-menu-grid button:focus{background:#f5f5f5;color:#111}
.native-menu-hint{font-size:20px;line-height:28px;color:#bcbcbc;margin:32px 0 0}
#exit-confirm{position:absolute;left:0;top:0;width:1920px;height:1080px;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.72);z-index:40}
.player-confirm{width:864px;padding:48px;border-radius:24px;background:#1f1f1f;border:1px solid #444;box-shadow:0 24px 80px rgba(0,0,0,.56)}
.player-confirm h2{font-size:36px;line-height:40px;letter-spacing:-.5px;margin:0 0 16px}
.player-confirm>p{font-size:24px;line-height:32px;color:#bcbcbc;margin:0 0 40px}
.confirm-actions{display:flex;align-items:center}
.confirm-actions button{margin-right:24px;white-space:nowrap}
.confirm-actions button:last-child{margin-right:0}
/* TV layout follows the full-screen artwork and floating navigation of Apple TV. */
#stage{background:#000}
#content{background:#000}
#content.route-home{left:0;width:1920px;padding:0}
.view-home{padding:0 80px 64px}
.view-home>.error{margin-top:160px}
.view-home>.grid:not(.home-rail){padding-top:160px}
.home-topbar{position:absolute;left:80px;right:80px;top:48px;display:flex;align-items:center;justify-content:space-between;z-index:6}
.home-menu{display:flex;align-items:center;color:#f5f5f5;background:rgba(31,31,31,.8);border:1px solid rgba(255,255,255,.12);border-radius:32px;padding:16px 24px;font-size:24px;line-height:32px;font-weight:700}
.home-menu .icon{margin-right:12px}
.home-menu .brand-logo{width:32px;height:32px;margin-right:12px}
.home-menu:focus{background:#f5f5f5;color:#111}
.home-menu:focus .brand-logo{filter:brightness(0)}
.home-screen #sidebar:not(.expanded){width:0;padding:0;background:transparent}
.home-screen #sidebar:not(.expanded)>*{display:none}
#navigation button{transition:transform 150ms cubic-bezier(.2,0,0,1)}
.sidebar-open #content{opacity:.85}
.featured{height:880px;width:1920px;margin-left:-80px;border-radius:0;background:#181818}
.featured-art{left:0;right:0;top:0;width:100%;height:100%}
.featured-art img{object-position:50% 32%}
.featured-scrim{position:absolute;top:0;left:0;right:0;bottom:0;background:linear-gradient(0deg,#000 0%,rgba(0,0,0,.04) 64%),linear-gradient(90deg,rgba(0,0,0,.9) 0%,rgba(0,0,0,.6) 35%,rgba(0,0,0,.06) 75%);z-index:1}
.featured-body{position:absolute;left:80px;bottom:112px;width:880px;height:auto;padding:0;display:block;z-index:2}
.featured-body .eyebrow{font-size:20px;line-height:28px;letter-spacing:1px;color:#fff;margin-bottom:16px}
.featured-title{font-size:72px;line-height:80px;letter-spacing:-2px;max-width:880px}
.featured-meta{font-size:20px;line-height:28px;color:#ddd;margin-top:16px}
.featured-description{font-size:24px;line-height:32px;color:#ddd;max-width:640px;margin:16px 0 0;-webkit-line-clamp:2}
.featured-slide.long-title .featured-description{display:-webkit-box}
.featured .actions,.featured-slide.long-title .actions{margin-top:32px;margin-bottom:0;align-items:center}
.featured .actions button{height:72px;padding:16px 32px;border-radius:36px;margin:0 16px 0 0}
.featured .actions .primary{min-width:224px}
.featured .actions .favorite-action{width:72px;min-width:72px;padding:20px;background:rgba(31,31,31,.8);border:1px solid rgba(255,255,255,.16)}
.featured .favorite-action .icon{width:30px;height:30px;margin:0}
.featured .favorite-action .button-label{display:none}
.featured .favorite-action:focus{background:#f5f5f5;color:#111}
.featured-pager{bottom:112px;right:80px}
.featured-pager .circle-button{width:64px;height:64px;border-radius:32px;padding:20px;background:rgba(31,31,31,.8)}
.featured-pager .circle-button:focus{background:#f5f5f5;color:#111}
.featured-position{display:none}
.featured-dots{position:absolute;z-index:4;left:50%;bottom:32px;transform:translateX(-50%);display:flex;align-items:center;background:rgba(31,31,31,.72);padding:8px 12px;border-radius:16px}
.featured-dots span{display:block;width:8px;height:8px;border-radius:4px;background:rgba(255,255,255,.35);margin:0 4px}
.featured-dots .active{position:relative;width:40px;overflow:hidden;background:rgba(255,255,255,.24)}
.featured-dots .featured-progress{position:absolute;left:0;top:0;width:100%;height:100%;margin:0;background:#fff;transform:scaleX(0);transform-origin:left center;transition:transform 250ms linear}
.featured-empty{position:absolute;left:80px;right:80px;top:45%;margin:0;color:#bcbcbc;font-size:24px;line-height:32px;text-align:center}
.view-home .section-heading{margin:24px 0 16px}
/* Five complete covers; four 24px gaps. Padding keeps the focus ring visible. */
.home-rail{grid-template-columns:none;grid-auto-flow:column;grid-auto-columns:calc((100% - 96px)/5);overflow-x:auto;overflow-y:hidden;grid-gap:24px;padding:12px 8px;margin:-12px -8px 0;scrollbar-width:none}
.home-rail::-webkit-scrollbar{display:none}
.view-home .home-rail .poster-wrap{height:0;padding-bottom:calc(56.25% - 2px);border-radius:12px}
.home-rail .poster-wrap img{position:absolute;top:0;left:0;object-position:50% 28%}
.rail-all-art{position:absolute;left:0;top:0;right:0;bottom:0;display:flex;align-items:center;justify-content:center}
.rail-all-art .icon{width:48px;height:48px}
.rail-all-card:focus .poster-wrap,.rail-all-card:hover .poster-wrap{background:#f5f5f5;color:#111}
.primary,.secondary{border-radius:32px}
.native-controls{left:80px;right:80px;padding:0;background:transparent;border:0;border-radius:0}
.native-controls:before{content:'';position:absolute;z-index:-1;left:-80px;right:-80px;top:-160px;bottom:-112px;pointer-events:none;background:linear-gradient(0deg,rgba(0,0,0,.9) 0%,rgba(0,0,0,.64) 65%,transparent 100%)}
.native-actions .native-control{border-radius:44px;background:rgba(49,49,49,.88)}
.native-actions .native-control:focus{background:#f5f5f5;color:#111}
.native-menu,.player-confirm{border-radius:32px}
#player-hint{background:transparent;color:#ccc}
/* Chromium 69 paints square outlines. Shadows follow each control's own radius. */
button:focus,input:focus,select:focus{outline:none;box-shadow:0 0 0 2px #000,0 0 0 5px #fff}
button:focus{transition:none}
button:disabled:active{transform:none}
#navigation button:focus{box-shadow:none}
.movie-card:focus{box-shadow:none}
.movie-card:focus .poster-wrap,.movie-card:focus:hover .poster-wrap{box-shadow:0 0 0 4px #fff;transform:none;transition:none}
.movie-card:focus .movie-title{color:#fff}
.movie-card:focus .movie-meta{color:#ccc}
.home-section{position:relative}
.rail-controls{display:flex;align-items:center;flex-shrink:0}
.rail-arrow{background:#272727}
.rail-arrow[aria-disabled=true]{color:#666;background:#181818}
.rail-arrow[aria-disabled=true]:focus{color:#111;background:#fff}
.home-rail{position:relative;scroll-behavior:auto}
#content::-webkit-scrollbar{display:block;width:6px}
#content::-webkit-scrollbar-thumb{background:#555;border-radius:3px}
#content::-webkit-scrollbar-track{background:transparent}
.native-menu{scroll-padding:32px}
@media(prefers-reduced-motion:reduce){button,.poster-wrap{transition:none}.page-view,.featured-slide{transition:opacity 120ms ease;transform:none!important}.movie-card:focus .poster-wrap,button:active{transform:none}}

@media(prefers-reduced-motion:reduce){#sidebar-scrim{transition:none}}

@media(prefers-reduced-motion:reduce){.featured-dots .featured-progress{transition:none}}
.featured-art.artwork-poster-fallback{background:#101010}
.featured-art.artwork-poster-fallback img{position:absolute;left:0;right:0;top:0;bottom:0;width:100%;height:100%;object-fit:cover;object-position:50% 32%;filter:blur(32px);transform:scale(1.08);opacity:.55}
.artwork-credit{position:absolute;right:80px;bottom:16px;z-index:2;font-size:14px;line-height:20px;color:rgba(255,255,255,.65);text-decoration:none}

pages.css.content:
/* Shared Apple TV composition for the library, search and film pages. */
#content{padding:64px;background:#000}
#sidebar:not(.expanded){background:#000}
.page-header{align-items:flex-start;margin-bottom:40px;min-height:88px}
.page-heading{min-width:0}
.page-header h1{font-size:60px;line-height:1;letter-spacing:-2px;max-width:1120px}
.page-subtitle{font-size:24px;line-height:32px;color:#a0a0a0;margin:16px 0 0}
.header-tools{padding-top:8px}
.grid:not(.home-rail){grid-template-columns:repeat(4,minmax(0,1fr));grid-gap:32px 24px}
.grid:not(.home-rail) .poster-wrap{height:226px;border-radius:12px}
.grid:not(.home-rail) .poster-wrap img{object-position:50% 32%}
.grid:not(.home-rail) .movie-title{font-size:24px;line-height:32px;padding-top:16px}
.grid.poster-grid{grid-template-columns:repeat(6,minmax(0,1fr))}
.grid.poster-grid .poster-wrap{height:392px}
.grid.poster-grid .movie-title{font-size:20px;line-height:28px}
.movie-meta{color:#a0a0a0}
.movie-card{align-self:start}
.poster-wrap .ratings-card{position:absolute;top:12px;left:12px;right:12px;margin:0;z-index:1}
.ratings{display:flex;align-items:center;flex-wrap:wrap}
.rating-chip{display:inline-flex;align-items:center;flex-shrink:0;height:36px;background:#181818;border:0;border-radius:999px;padding:4px 8px 4px 4px;white-space:nowrap;margin-right:8px;font-size:18px;line-height:28px}
.rating-chip:last-child{margin-right:0}
.rating-brand{display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;min-width:32px;height:28px;padding:0 8px;border-radius:999px;font-size:14px;line-height:20px;font-weight:700;letter-spacing:0;color:#111;margin-right:8px}
.rating-value{color:#fff;font-size:20px;line-height:28px;font-weight:700;font-variant-numeric:tabular-nums;letter-spacing:0}
.rating-kp .rating-brand,.rating-stat.rating-kp .rating-stat-source{background:#ff6b25}
.rating-imdb .rating-brand,.rating-stat.rating-imdb .rating-stat-source{background:#f5c518}
.ratings-inline{margin-top:16px}
.ratings-inline .rating-chip{height:40px;padding:4px 12px 4px 4px;margin-right:12px}
.ratings-inline .rating-chip:last-child{margin-right:0}
.ratings-inline .rating-brand{height:32px;padding:0 8px;font-size:18px;line-height:28px}
.ratings-inline .rating-value{font-size:24px;line-height:32px}
.filters{margin:0 0 24px;padding:24px 0 0}
.filters label{font-size:18px;line-height:28px;color:#929292;margin-right:24px}
.filters select{min-width:224px;max-width:320px;background:#1f1f1f;border-color:#313131;border-radius:24px;padding:12px 24px}
.load-more{margin:48px 0 24px}
.load-more .count{font-size:18px;line-height:28px;margin-bottom:24px}
.load-more button{min-width:256px}
.empty,.error{padding:80px 64px;background:#181818;text-align:center;border-radius:24px;max-width:1200px;margin:48px auto}
.empty>.icon{width:64px;height:64px;color:#777;margin-bottom:24px}
.empty h2,.error h2{font-size:36px;line-height:40px}
.empty p,.error p{max-width:800px;margin:16px auto 32px;font-size:24px;line-height:32px}
.empty .primary,.error .primary{min-width:224px}
.library-toolbar{display:flex;align-items:center;margin:8px 0 40px;padding:4px;background:#181818;border-radius:32px;width:max-content}
.library-tab{border:0;background:transparent;color:#a0a0a0;border-radius:28px;padding:12px 24px;font-size:20px;line-height:28px;font-weight:700}
.library-tab.selected{background:#313131;color:#fff}
.library-tab:focus{background:#fff;color:#111}
.search-form{margin:8px 0 48px;align-items:stretch}
.search-field{position:relative;flex:1;min-width:0;margin-right:24px}
.search-field>.icon{position:absolute;left:32px;top:26px;width:32px;height:32px;color:#a0a0a0;pointer-events:none}
.search-form input{display:block;width:100%;height:88px;margin:0;padding:24px 32px 24px 80px;border-radius:24px;font-size:30px;line-height:36px;background:#1f1f1f;border:1px solid #313131}
.search-form>.primary{min-width:208px;border-radius:24px}
.search-form input::-webkit-search-cancel-button{-webkit-appearance:none}
.search-form input{padding-right:88px}
.search-clear{position:absolute;right:16px;top:16px;width:56px;height:56px;min-height:56px;padding:12px;border:0;border-radius:28px;background:transparent;color:#bcbcbc}
.search-clear .icon{width:32px;height:32px;margin:0}
.search-clear .button-label{display:none}
.search-clear:focus,.search-clear:hover{background:#f5f5f5;color:#111}
.search-query-caption{font-size:20px;line-height:28px;color:#bcbcbc;margin:0 0 24px;overflow-wrap:break-word}
.search-tabs{margin-bottom:24px}
.search-status{font-size:20px;line-height:28px;margin:0 0 24px}
.search-recent{margin:0 0 48px}
.search-recent h2,.search-discovery h2{font-size:30px;line-height:36px;letter-spacing:-.5px;margin:0 0 24px}
.query-list{display:flex;flex-wrap:wrap}
.query-chip{font-size:20px;line-height:28px;padding:12px 24px;margin:0 16px 16px 0;max-width:480px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;background:#1f1f1f}
.browse-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-gap:24px}
.browse-tile{height:224px;position:relative;display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-end;background:#1f1f1f;color:#fff;border:1px solid #313131;border-radius:16px;padding:32px;font-size:30px;line-height:36px;font-weight:700;text-align:left}
.browse-tile>.icon{width:64px;height:64px;color:#a0a0a0;margin-bottom:24px}
.browse-tile:focus{background:#f5f5f5;color:#111}
.browse-tile:focus>.icon{color:#444}
.collection-grid{grid-template-columns:repeat(3,minmax(0,1fr));grid-gap:24px;margin-top:8px;align-items:stretch}
.collection{position:relative;display:flex;flex-direction:column;align-items:flex-start;justify-content:space-between;min-width:0;min-height:232px;padding:32px;border-radius:24px;background:#1f1f1f;white-space:normal;overflow:visible;border-color:rgba(255,255,255,.08)}
.collection-top{display:flex;align-items:center;justify-content:space-between;width:100%;margin-bottom:24px;flex-shrink:0}
.collection-symbol{display:flex;align-items:center;justify-content:center;width:48px;height:48px;border-radius:12px;background:rgba(255,255,255,.08);color:#bcbcbc}
.collection-symbol .icon{width:32px;height:32px}
.collection-symbol.collection-brand{width:128px;padding:0;justify-content:flex-start;background:transparent;color:#fff}
.collection-symbol.collection-brand-square{width:48px;padding:0}
.collection-brand-logo{display:block;width:100%;max-width:104px;height:32px;object-fit:contain;object-position:left center}
.collection-brand-square .collection-brand-logo{max-width:48px;height:48px}
.collection-arrow{position:absolute;right:32px;display:flex;align-items:center;justify-content:center;color:#929292;width:32px;height:32px}
.collection-arrow .icon{width:32px;height:32px}
.collection-name{display:block;width:100%;min-width:0;padding-bottom:4px;font-size:30px;line-height:36px;font-weight:700;letter-spacing:-.5px;white-space:normal;word-wrap:break-word;overflow-wrap:break-word}
.collection-tail{display:inline-block;max-width:100%;vertical-align:top;white-space:normal}
.collection:focus{border-color:transparent}
.collection:focus .collection-symbol{color:#111;background:rgba(0,0,0,.08)}
.collection:focus .collection-brand{color:#111;background:transparent}
.collection:focus [data-brand="appletv"] .collection-brand-logo,.collection:focus [data-brand="hbo"] .collection-brand-logo{filter:brightness(0)}
.collection:focus [data-brand="hulu"] .collection-brand-logo{filter:brightness(.45)}
.collection:focus .collection-arrow{color:#555}
@media(hover:hover) and (pointer:fine){.collection:hover:not(:focus){background:#272727}}
.settings-shell{display:flex;align-items:flex-start;margin-top:48px}
.settings-intro{width:544px;margin-right:80px;padding-top:32px;flex-shrink:0}
.settings-intro>.icon{width:80px;height:80px;color:#929292;margin-bottom:32px}
.settings-intro h2{font-size:36px;line-height:40px;letter-spacing:-.5px;margin:0 0 24px}
.settings-intro p{font-size:24px;line-height:36px;color:#a0a0a0;margin:0 0 32px}
/* Film pages continue the artwork to the edges, then reveal the information below. */
#content.route-detail{left:0;width:1920px;padding:0}
.detail-screen #sidebar:not(.expanded){width:0;padding:0;background:transparent}
.detail-screen #sidebar:not(.expanded)>*{display:none}
.detail-topbar{position:absolute;z-index:6;left:80px;right:80px;top:48px;display:flex;align-items:center;justify-content:space-between}
.detail-topbar .detail-back{margin:0;background:rgba(31,31,31,.8);color:#fff;padding:16px 24px;border-radius:32px}
.detail-topbar .detail-back:focus{background:#fff;color:#111}
.detail{position:relative;display:block}
.detail-hero{position:relative;height:880px;background:#181818;overflow:hidden}
.detail-art{position:absolute;left:0;right:0;top:0;bottom:0;background:#181818}
.detail-art img{width:100%;height:100%;display:block;object-fit:cover;object-position:50% 30%}
.detail-scrim{position:absolute;left:0;right:0;top:0;bottom:0;background:linear-gradient(0deg,#000 0%,rgba(0,0,0,.02) 72%),linear-gradient(90deg,rgba(0,0,0,.94) 0%,rgba(0,0,0,.66) 38%,rgba(0,0,0,.06) 80%)}
.detail-content{position:absolute;z-index:2;left:80px;bottom:80px;max-width:1040px;padding:0;margin:0}
.detail-content>.eyebrow{font-size:20px;line-height:28px;letter-spacing:1px;color:#ddd;margin-bottom:16px}
.detail-content h1{font-size:72px;line-height:80px;letter-spacing:-2px;margin:0 0 16px;max-width:1040px;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}
.original-title{font-size:24px;line-height:32px;color:#a0a0a0;margin:0 0 16px}
.detail-content .metadata{display:flex;align-items:center;flex-wrap:wrap;margin:0;color:#ddd;font-size:20px;line-height:28px;max-width:960px}
.meta-part{margin-right:16px}
.media-tag{display:inline-block;font-size:14px;line-height:20px;max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border:1px solid rgba(255,255,255,.5);border-radius:4px;padding:0 4px;margin-right:12px;color:#ddd}
.detail-summary{max-width:800px;font-size:24px;line-height:32px;color:#ddd;margin:24px 0 0;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}
.detail-content .actions{margin:32px 0 0;align-items:center;flex-wrap:nowrap}
.detail-content .actions button{height:72px;padding:16px 32px;border-radius:36px;margin:0 16px 0 0;white-space:nowrap}
.detail-content .actions .primary{min-width:224px}
.detail-content .actions .detail-favorite{width:72px;min-width:72px;padding:20px;border:1px solid rgba(255,255,255,.16);background:rgba(31,31,31,.8)}
.detail-favorite .icon{width:30px;height:30px;margin:0}
.detail-favorite .button-label{display:none}
.detail-content .actions .detail-favorite:focus{background:#fff;color:#111}
.detail-content .source-caption{margin:16px 0 0}
.detail-about{position:relative;padding:24px 80px 80px;background:#000}
.detail-about>.section-heading{margin:0 0 32px}
.detail-about>.section-heading h2{font-size:36px;line-height:40px}
.detail-info-grid{display:grid;grid-template-columns:2fr 1fr 1fr;grid-gap:24px;align-items:start}
.info-panel{background:#1f1f1f;border-radius:16px;padding:32px;min-width:0;min-height:384px}
.info-panel h3{font-size:24px;line-height:32px;font-weight:700;margin:0 0 24px}
.about-overview .description{font-size:24px;line-height:36px;color:#bcbcbc;margin:0;max-width:none;white-space:normal}
.description-collapsed:not(.description-expanded) .description{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:7;overflow:hidden}
.about-overview .text-button{margin:24px 0 0;padding:8px 12px;background:#313131;border-radius:24px}
.about-overview .text-button:focus{background:#fff;color:#111}
.rating-stat{margin:0 0 24px}
.rating-stat-value{display:flex;align-items:baseline;font-variant-numeric:tabular-nums}
.rating-stat-value strong{font-size:48px;line-height:1;letter-spacing:-1px;color:#fff}
.rating-stat-value>span{font-size:20px;line-height:28px;color:#777;margin-left:8px}
.rating-stat-source{display:inline-block;font-size:18px;line-height:28px;font-weight:700;color:#111;margin-top:8px;padding:0 8px;border-radius:999px}
.rating-note,.rating-empty{font-size:18px;line-height:28px;color:#929292;margin:24px 0 0}
.film-facts{margin:0}
.film-facts dt{font-size:18px;line-height:28px;color:#929292;margin:16px 0 0}
.film-facts dt:first-child{margin-top:0}
.film-facts dd{font-size:20px;line-height:28px;color:#ddd;margin:4px 0 0;overflow-wrap:break-word}
.cast-section{margin-top:48px}
.cast-section h2{font-size:30px;line-height:36px;margin:0 0 32px}
.cast-list{display:flex;flex-wrap:wrap}
.cast-person{width:192px;margin:0 24px 24px 0;text-align:center}
.cast-initials{width:128px;height:128px;margin:0 auto;background:#272727;border:1px solid #444;border-radius:64px;display:flex;align-items:center;justify-content:center;font-size:36px;line-height:40px;color:#a0a0a0}
.cast-avatar{position:relative;overflow:hidden}
.cast-avatar img{position:absolute;top:0;left:0;width:100%;height:100%;object-fit:cover;object-position:center 25%;border-radius:inherit}
.cast-person p{font-size:20px;line-height:28px;margin:16px 0 0;color:#bcbcbc}
.detail-return-bottom{margin-top:40px}
.detail-seasons-section{position:relative;padding:24px 80px 48px;background:#000}
.detail-seasons-section>.section-heading{margin:0 0 16px}
.detail-seasons-section h2{font-size:30px;line-height:36px;margin:0}
.detail-seasons-help,.detail-seasons-empty{font-size:20px;line-height:28px;color:#929292;margin:0 0 24px}
.detail-season-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));grid-gap:24px}
.detail-season-card{display:flex;align-items:center;justify-content:space-between;min-height:128px;padding:24px 32px;border:1px solid #444;border-radius:16px;background:#1f1f1f;color:#f5f5f5;text-align:left}
.detail-season-copy{display:block;min-width:0}
.detail-season-copy strong{display:block;font-size:24px;line-height:32px;font-weight:700}
.detail-season-copy>span{display:block;font-size:18px;line-height:28px;color:#929292;margin-top:8px}
.detail-season-card>.icon{width:32px;height:32px;margin-left:24px}
.detail-season-card:focus{background:#f5f5f5;color:#111;border-color:transparent}
.detail-season-card:focus .detail-season-copy>span{color:#555}
@media(prefers-reduced-motion:reduce){.rating-chip{transition:none}}


.home-releases-status,.home-release-empty{font-size:18px;line-height:28px;color:#929292;margin:24px 0}
.release-tabs{margin-bottom:32px}
/* Keep artwork edge to edge inside the hero, including the poster wash. */
.detail-art.artwork-poster-fallback{background:#101010}
.detail-art.artwork-poster-fallback img{position:absolute;left:0;right:0;top:0;bottom:0;width:100%;height:100%;object-fit:cover;object-position:50% 30%;filter:blur(32px);transform:scale(1.08);opacity:.55}
.cast-credit{display:block;font-size:16px;line-height:24px;color:#a0a0a0;text-decoration:none;margin-top:8px}
.metadata-attribution{margin-top:48px;color:#929292;font-size:16px;line-height:24px;max-width:1120px}
.metadata-attribution img{display:block;width:128px;height:24px;object-fit:contain;object-position:left center;margin-bottom:16px}
.metadata-attribution p{margin:8px 0 0}

player.css.content:
/* TV playback: separate title, timeline and actions, with a dedicated settings drawer. */
#player .native-controls{position:absolute;left:0;right:0;top:0;bottom:0;padding:0;border:0;border-radius:0;background:transparent;pointer-events:none;z-index:5}
#player .native-controls:before{content:'';position:absolute;left:0;right:0;top:0;bottom:auto;height:256px;z-index:-1;background:linear-gradient(180deg,rgba(0,0,0,.8),rgba(0,0,0,0))}
#player .native-controls:after{content:'';position:absolute;left:0;right:0;bottom:0;height:480px;z-index:-1;background:linear-gradient(0deg,rgba(0,0,0,.94),rgba(0,0,0,.64) 50%,rgba(0,0,0,0))}
#player .native-now{position:absolute;left:80px;right:80px;top:48px;display:grid;grid-template-columns:256px minmax(0,1fr) 256px;grid-column-gap:24px;align-items:center;min-height:80px}
#player #native-exit{display:flex;align-items:center;justify-content:center;grid-column:1;margin:0;min-width:0;width:64px;height:64px;padding:16px;border:1px solid rgba(255,255,255,.14);border-radius:32px;background:rgba(31,31,31,.72);color:#fff;font-size:20px;line-height:28px;pointer-events:auto;flex-shrink:0}
#player #native-exit .icon{width:24px;height:24px;margin:0}
#player #native-exit .control-copy{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
#player #native-exit:focus{background:#fff;color:#111}
#player .native-now-copy{grid-column:2;min-width:0;text-align:center}
#player .native-now-title{font-size:36px;line-height:40px;letter-spacing:-.5px;max-width:100%}
#player .native-now-episode{font-size:20px;line-height:28px;color:#bcbcbc;margin:8px 0 0}
#player .native-state{grid-column:3;justify-self:end;max-width:100%;overflow:hidden;text-overflow:ellipsis;font-size:18px;line-height:28px;background:rgba(31,31,31,.8);padding:8px 16px;border:1px solid rgba(255,255,255,.12);border-radius:16px;margin:0;white-space:nowrap}
#player .native-bottom{position:absolute;left:80px;right:80px;bottom:48px}
#player .native-timeline{position:relative;display:flex;align-items:center;flex:none;width:100%;height:40px;margin:0;background:transparent;border-radius:0;overflow:visible;pointer-events:auto;cursor:pointer}
#player .native-timeline:focus{outline:none;box-shadow:none}
#player .native-track{height:6px;width:100%;position:relative;background:rgba(255,255,255,.24);border-radius:3px}
#player .native-timeline-fill,#player .native-buffer-fill{position:absolute;left:0;top:0;width:100%;height:100%;display:block;border-radius:3px;transform:scaleX(0);transform-origin:left center}
#player .native-timeline-fill{background:#f5f5f5}
#player .native-buffer-fill{background:rgba(255,255,255,.28)}
#player .native-seek-knob{position:absolute;left:0;top:50%;width:16px;height:16px;border-radius:8px;background:#fff;transform:translate(-50%,-50%);opacity:0}
#player .native-timeline:focus .native-seek-knob{opacity:1;box-shadow:0 0 0 3px #000,0 0 0 6px #fff}
#player .native-timeline[aria-disabled=true]{opacity:.45;cursor:default}
#player .native-seek-bubble{position:absolute;left:0;bottom:64px;width:160px;transform:translateX(-50%);text-align:center;border:1px solid rgba(255,255,255,.2);border-radius:16px;background:#1f1f1f;color:#fff;font-size:30px;line-height:36px;font-weight:700;padding:16px;box-shadow:0 12px 32px rgba(0,0,0,.32);font-variant-numeric:tabular-nums}
#player .native-time-row{display:flex;align-items:center;justify-content:center;margin:0 0 32px;color:#ccc;white-space:nowrap}
#player .native-time{min-width:0;font-size:20px;line-height:28px;font-variant-numeric:tabular-nums;color:#fff}
#player .native-total-time{margin-left:16px;color:#929292}
#player .native-total-time:before{content:'/';margin-right:16px;color:#777}
#player .native-remaining{margin-left:24px;font-size:18px;line-height:28px;color:#a0a0a0;font-variant-numeric:tabular-nums}
#player .native-actions{display:grid;grid-template-columns:minmax(0,1fr) 280px minmax(0,1fr);align-items:center;min-height:124px}
#player .native-audio-group{grid-column:1;display:flex;align-items:center;min-width:0;padding-bottom:28px}
#player .native-transport{grid-column:2;display:grid;grid-template-columns:72px 88px 72px;grid-column-gap:24px;align-items:center;padding-bottom:28px;min-width:0}
#player .native-actions .native-control{position:relative;display:inline-flex;align-items:center;justify-content:center;border:1px solid rgba(255,255,255,.12);color:#f5f5f5;background:rgba(31,31,31,.8);font-size:20px;line-height:28px;padding:16px;min-height:72px;min-width:0;margin:0;pointer-events:auto;flex-shrink:0}
#player .native-actions .native-control:focus{color:#111;background:#f5f5f5}
#player .native-transport .native-control{width:72px;height:72px;border-radius:36px;padding:20px}
#player .native-transport #native-previous{grid-column:1}
#player .native-transport #native-next{grid-column:3}
#player .native-transport .native-control .icon{width:32px;height:32px;margin:0}
#player .native-transport .control-copy{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
#player .native-transport .control-label{font-size:18px;line-height:28px;font-weight:400}
#player .native-transport #native-toggle{grid-column:2;width:88px;height:88px;border-radius:44px;padding:24px}
#player #native-toggle .icon{width:40px;height:40px}
#player .native-tools{grid-column:3;display:flex;align-items:center;justify-content:flex-end;min-width:0;padding-bottom:28px}
#player .native-tools .native-control,#player .native-audio-group .native-control{min-width:128px;max-width:256px;height:80px;border-radius:16px;padding:12px 16px;margin-left:12px}
#player .native-tools .native-control:first-child{margin-left:0}
#player .native-tools .native-control .icon,#player .native-audio-group .native-control .icon{width:24px;height:24px;margin-right:12px}
#player .native-tools .control-label,#player .native-audio-group .control-label{font-size:20px;line-height:28px}
#player .native-tools .control-caption,#player .native-audio-group .control-caption{font-size:16px;line-height:24px;max-width:192px;color:#a0a0a0;margin-top:0}
#player .native-tools .native-control:focus .control-caption,#player .native-audio-group .native-control:focus .control-caption{color:#555}
#player .native-audio-group #native-audio{min-width:176px;max-width:320px;margin-left:0;padding-right:32px;border-radius:40px}
#player #native-audio .icon{width:40px;height:40px}
#player .native-tools #native-episodes{min-width:144px;max-width:256px;border-radius:40px}
#player #native-episodes .icon{width:40px;height:40px}
#player .native-tools #native-settings{min-width:80px;max-width:80px;width:80px;height:80px;padding:24px;border-radius:40px}
#player #native-settings .icon{width:32px;height:32px;margin:0}
#player #native-settings .control-copy{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
#player .native-settings-badge{position:absolute;top:-8px;right:-8px;min-width:32px;height:24px;padding:0 4px;border:2px solid #181818;border-radius:8px;background:#f5f5f5;color:#111;font-size:14px;line-height:20px;font-weight:700;text-align:center;pointer-events:none}
#player .native-remaining:empty{display:none}
#player .native-control:disabled{opacity:.4}
#player #player-hint{display:none!important}
#player #player-status{top:40%;left:560px;right:560px;border:1px solid rgba(255,255,255,.14);border-radius:24px;padding:32px;background:rgba(24,24,24,.92);font-size:24px;line-height:36px;color:#ddd}
#player #player-toolbar{display:grid;grid-template-columns:256px minmax(0,1fr) 256px;grid-auto-rows:minmax(80px,auto);grid-column-gap:24px;align-items:center;left:0;right:0;top:0;padding:48px 80px 96px;background:linear-gradient(180deg,rgba(0,0,0,.88),transparent);color:#fff}
#player #player-toolbar button{border-radius:32px;background:rgba(31,31,31,.8);border:1px solid rgba(255,255,255,.14);padding:16px 24px}
#player #player-toolbar button:focus{background:#fff;color:#111}
#player #player-back{display:flex;align-items:center;justify-content:center;grid-column:1;width:64px;height:64px;padding:16px;margin:0}
#player #player-back .icon{width:24px;height:24px;margin:0}
#player #player-title{grid-column:2;min-width:0;padding:0;text-align:center;font-size:36px;line-height:40px}
#player #player-retry{grid-column:3;justify-self:end;margin:0;max-width:100%}
#player .native-menu-shade{position:absolute;left:0;right:0;top:0;bottom:0;background:rgba(0,0,0,.4);z-index:9}
#player .native-menu{position:absolute;left:auto;right:48px;top:48px;bottom:48px;width:640px;height:984px;max-height:none;padding:32px;background:#181818;border:1px solid #444;border-radius:24px;z-index:10;display:flex;flex-direction:column;overflow:visible;box-shadow:0 24px 80px rgba(0,0,0,.5)}
#player .native-menu-header{display:flex;align-items:center;justify-content:space-between;flex-shrink:0}
#player .native-menu h2{font-size:36px;line-height:40px;margin:0;letter-spacing:-.5px;max-width:calc(100% - 72px)}
#player .native-menu-close{width:48px;height:48px;display:flex;align-items:center;justify-content:center;background:#313131;border:0;border-radius:24px;color:#fff;padding:12px;flex-shrink:0;margin-left:16px}
#player .native-menu-close svg{width:24px;height:24px;fill:currentColor}
#player .native-menu-close:focus{background:#fff;color:#111}
#player .native-menu-context{font-size:20px;line-height:28px;color:#929292;margin:16px 0 32px;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;flex-shrink:0}
#player .native-menu-scroll{position:relative;flex:1;min-height:0;overflow-y:auto;padding:8px;margin:-8px;scrollbar-width:none}
#player .native-menu-scroll::-webkit-scrollbar{width:4px}
#player .native-menu-scroll::-webkit-scrollbar-thumb{background:#555;border-radius:2px}
#player .native-menu-grid{display:grid;grid-template-columns:1fr;grid-gap:8px}
#player .native-menu-grid .native-choice{display:flex;align-items:center;justify-content:space-between;width:100%;min-height:88px;padding:16px 24px;border:1px solid transparent;background:#272727;border-radius:16px;color:#ddd;text-align:left}
#player .native-menu-grid .native-choice:disabled{opacity:.45;cursor:default}
#player .native-choice-copy{min-width:0;flex:1}
#player .native-choice-label{display:block;font-size:24px;line-height:32px;font-weight:700;overflow-wrap:break-word}
#player .native-choice-caption{display:block;font-size:18px;line-height:28px;color:#929292;margin-top:4px;font-weight:400}
#player .native-choice-check{display:block;width:28px;height:28px;flex-shrink:0;margin-left:24px}
#player .native-choice-check svg{width:28px;height:28px;fill:currentColor}
#player .native-menu-grid .native-choice.selected{border-color:#666;background:#313131;box-shadow:none}
#player .native-menu-grid .native-choice:focus{border-color:transparent;background:#fff;color:#111;box-shadow:0 0 0 2px #181818,0 0 0 5px #fff}
#player .native-choice:focus .native-choice-caption{color:#555}
#player .native-menu-hint{display:none}
#native-video::cue{font-family:Manrope,sans-serif;font-size:32px;color:#fff;background-color:rgba(0,0,0,.72)}
@media(prefers-reduced-motion:reduce){#player .native-control{transition:none}}

loading.css.content:
/* A restrained, twelve-segment activity indicator. Only opacity is animated. */
.loading-status{display:flex;align-items:center;justify-content:center;color:#e5e5e5;pointer-events:none}
.activity-indicator{position:relative;display:block;flex-shrink:0;width:64px;height:64px;color:inherit}
.activity-indicator>span{position:absolute;left:0;top:0;width:100%;height:100%;opacity:.2;animation:activity-pulse 1s linear infinite}
.activity-indicator>span:before{content:'';position:absolute;left:47%;top:4%;width:6%;height:25%;border-radius:8px;background:currentColor}
.page-loading{position:absolute;left:0;right:0;top:0;bottom:0;z-index:8;background:#101010}
.inline-loading{width:100%;min-height:80px}
.inline-loading .activity-indicator,button .activity-indicator{width:32px;height:32px}
#player-loading{position:absolute;left:0;right:0;top:0;bottom:0;z-index:4;display:none;background:transparent}
#player.native-loading #player-loading,#player.player-resolving #player-loading{display:flex;animation:activity-appear 150ms steps(1,end)}
#player.native-loading #player-status,#player.player-resolving #player-status{visibility:hidden}
@keyframes activity-pulse{0%{opacity:1}100%{opacity:.2}}
@keyframes activity-appear{from{opacity:0}to{opacity:1}}
@media(prefers-reduced-motion:reduce){.activity-indicator>span{animation-duration:2s}}

support.css.content:
/* Only the decorative light moves; the button and remote focus stay steady. */
.home-header-actions,.detail-header-actions{display:flex;align-items:center}
.support-control{position:relative;display:inline-flex;flex-shrink:0;margin-left:16px;border-radius:999px}
.support-control:first-child{margin-left:0}
.support-action{position:relative;z-index:1;display:inline-flex;align-items:center;justify-content:center;min-height:52px;padding:12px 24px;border:0;border-radius:999px;background:#f5f5f5;color:#111;font-size:20px;line-height:28px;font-weight:700;white-space:nowrap}
.support-action .icon{width:24px;height:24px;margin-right:12px}
.support-action .button-label,.support-close .button-label{display:inline}
.support-action:focus{background:#f5f5f5;color:#111}
.detail-header-actions .support-action{min-height:64px;padding-top:16px;padding-bottom:16px}
#support-modal{position:absolute;z-index:40;top:0;right:0;bottom:0;left:0;background:#000;color:#f5f5f5}
.support-header{position:absolute;top:48px;right:80px;left:80px;display:flex;align-items:center;justify-content:space-between}
#support-title{margin:0;font-size:36px;line-height:40px;font-weight:700;letter-spacing:-1px}
.support-close{display:inline-flex;align-items:center;justify-content:center;min-height:64px;padding:16px 24px;background:#242424;color:#fff;border:0;border-radius:999px;font-size:20px;line-height:28px;font-weight:700}
.support-close .icon{width:24px;height:24px;margin-right:12px}
.support-close:focus{background:#f5f5f5;color:#111}
.support-qr{position:absolute;top:130px;left:550px;display:block;width:820px;height:820px;object-fit:contain;background:#fff}
.support-help{position:absolute;bottom:48px;left:80px;right:80px;margin:0;text-align:center;font-size:20px;line-height:28px;color:#bcbcbc}
@media(hover:hover) and (pointer:fine){.support-action:hover{background:#dcdcdc}.support-action:focus:hover{background:#f5f5f5}}
@media(prefers-reduced-motion:reduce){.support-action,.support-close{transition:none}}

updates.css.content:
.update-control{position:relative;display:inline-flex;flex-shrink:0;border-radius:999px}
.update-action{position:relative;z-index:1;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;min-height:52px;padding:12px 24px;border:0;border-radius:999px;background:#f5f5f5;color:#111;font-size:20px;line-height:28px;font-weight:700;white-space:nowrap}
.update-action .icon{width:24px;height:24px;margin-right:12px}
.update-action .button-label{display:inline}
.update-action:focus{background:#f5f5f5;color:#111}
.detail-header-actions .update-action{min-height:64px;padding-top:16px;padding-bottom:16px}
#update-modal{position:absolute;z-index:41;left:0;top:0;width:1920px;height:1080px;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.72)}
.update-open .update-aura::before,.update-open .update-aura::after{animation-play-state:paused}

.update-aura{position:absolute;top:12px;right:12px;bottom:12px;left:12px;border-radius:999px;pointer-events:none;opacity:1;box-shadow:-20px -4px 40px 8px rgba(172,104,255,.9),20px 4px 40px 8px rgba(37,174,255,.85),0 16px 40px 8px rgba(255,79,155,.75);transition:opacity 150ms cubic-bezier(.2,0,0,1)}
.update-control:focus-within .update-aura{opacity:1}
.update-aura::before,.update-aura::after{content:"";position:absolute;top:0;right:0;bottom:0;left:0;border-radius:inherit;pointer-events:none;animation:update-light-flow 8s cubic-bezier(.77,0,.175,1) infinite}
.update-aura::before{box-shadow:-24px -4px 40px 8px rgba(172,104,255,.85),20px 4px 40px 8px rgba(37,174,255,.75)}
.update-aura::after{box-shadow:20px -4px 40px 8px rgba(255,79,155,.85),-20px 8px 40px 8px rgba(37,174,255,.75);animation-delay:-4s}
.support-motion-paused .update-aura::before,.support-motion-paused .update-aura::after{animation-play-state:paused}
@keyframes update-light-flow{0%,100%{opacity:.15;transform:translate3d(-8px,-2px,0) scale(.98)}50%{opacity:.85;transform:translate3d(8px,2px,0) scale(1.04)}}
@media(hover:hover) and (pointer:fine){.update-action:hover{background:#dcdcdc}.update-action:focus:hover{background:#f5f5f5}}
@media(prefers-reduced-motion:reduce){.update-aura,.update-action{transition:none}.update-aura::before,.update-aura::after{animation:none;opacity:0;transform:none}}

keyboard.css.content:
/* Fixed TV composition: keyboard and results remain available together. */
.view-search{height:100%;min-height:0}
#content.route-search{overflow:hidden}
.view-search>.page-header{height:108px;min-height:108px;margin-bottom:40px}
/* An explicit track and an out-of-flow scroller prevent Tizen 5.5 content sizing. */
.search-workspace{display:grid;grid-template-columns:704px minmax(0,1fr);grid-template-rows:minmax(0,1fr);grid-gap:48px;height:calc(100% - 148px);min-height:0;align-items:start}
.search-input-panel{min-width:0}
.view-search .search-form{display:block;margin:0}
.view-search .search-field{flex:none;margin:0;width:100%}
.view-search .search-field>.icon{z-index:1;top:28px}
.search-query-display{position:relative;display:flex;align-items:center;width:100%;height:88px;min-height:88px;padding:24px 80px;font-size:30px;line-height:36px;background:#1f1f1f;border:1px solid #313131;border-radius:24px;color:#f5f5f5;text-align:left;white-space:nowrap}
.search-query-display:focus{background:#272727}
.query-scroll{display:block;min-width:0;flex:1;overflow:hidden;white-space:pre}
.query-entry{display:inline-block;white-space:pre;vertical-align:middle}
.query-caret{display:none;vertical-align:-4px;width:2px;height:32px;background:#f5f5f5;margin:0 1px}
.query-editing .query-caret{display:inline-block}
.query-empty .query-entry{color:#929292}
.query-selected{background:#f5f5f5;color:#111;border-radius:4px}
.query-selected .query-caret{display:none}
.view-search .search-form>.primary{width:100%;height:64px;min-width:0;min-height:64px;padding:16px 24px;margin-top:16px;border-radius:24px;font-size:24px;line-height:32px}
.tv-keyboard{margin-top:24px}
.tv-keyboard-languages{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-gap:8px;margin-bottom:16px}
.tv-keyboard-languages .tv-key{height:56px;min-height:56px;font-size:20px;line-height:28px;color:#a0a0a0}
.tv-keyboard-languages .selected{color:#f5f5f5;background:#313131}
.tv-keyboard-letters{display:grid;grid-template-rows:repeat(3,72px);grid-row-gap:8px;height:232px}
.tv-keyboard-row{display:grid;grid-template-columns:repeat(24,minmax(0,1fr));grid-column-gap:4px}
.tv-keyboard-row .tv-key{height:72px;min-height:72px;padding:12px 4px}
.tv-key{display:flex;align-items:center;justify-content:center;width:100%;height:64px;min-height:64px;padding:12px 8px;border:0;border-radius:16px;background:#1f1f1f;color:#f5f5f5;font-size:30px;line-height:36px;text-align:center;white-space:nowrap}
.tv-key:focus,.tv-key:hover,.tv-keyboard-languages .tv-key:focus{background:#f5f5f5;color:#111}
.tv-key .icon{width:32px;height:32px;margin:0}
.tv-key svg{display:block;width:100%;height:100%}
.tv-keyboard-actions{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));grid-gap:8px;margin-top:16px}
.tv-keyboard-actions .tv-key{font-size:24px;line-height:32px}
.tv-key-space{grid-column:span 3}
.search-results-panel{position:relative;height:100%;min-height:0;min-width:0;overflow:hidden}
.search-results-scroll{position:absolute;top:0;right:0;bottom:0;left:0;min-height:0;overflow-x:hidden;overflow-y:auto;padding:8px;scrollbar-width:thin;scrollbar-color:#444 transparent}
.search-results-scroll::-webkit-scrollbar{width:4px}
.search-results-scroll::-webkit-scrollbar-thumb{background:#444;border-radius:2px}
.search-results-scroll>.section-heading{margin:0 0 16px}
.search-results-scroll .grid:not(.home-rail){grid-template-columns:repeat(3,minmax(0,1fr))}
.search-results-scroll .grid .poster-wrap{position:relative;height:0;padding-bottom:calc(56.25% - 2px)}
.search-results-scroll .grid .poster-wrap img{position:absolute;left:0;top:0}
.search-results-scroll .grid .movie-title{font-size:20px;line-height:28px}
.search-results-scroll .browse-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
.search-results-scroll .browse-tile{height:200px;padding:24px;font-size:24px;line-height:32px}
.search-results-scroll .search-recent{margin-bottom:32px}
.search-panel-loading{position:absolute;z-index:3;left:0;top:0;right:0;bottom:0;background:#000;display:flex;align-items:center;justify-content:center;pointer-events:none}

#keyboard-backspace svg{fill:none}
